#!/bin/bash
# BASE Icon Updater — macOS kompatibel

echo ""
echo "🔄 BASE Icon Update startet..."
echo ""

rm -f icon.png icon.jpg icon-*.png icon-maskable.png

echo "" | base64 -D > icon-32.png 2>/dev/null || echo "" | base64 --decode > icon-32.png && echo "✅ icon-32.png"
echo "" | base64 -D > icon-48.png 2>/dev/null || echo "" | base64 --decode > icon-48.png && echo "✅ icon-48.png"
echo "" | base64 -D > icon-76.png 2>/dev/null || echo "" | base64 --decode > icon-76.png && echo "✅ icon-76.png"
echo "" | base64 -D > icon-120.png 2>/dev/null || echo "" | base64 --decode > icon-120.png && echo "✅ icon-120.png"
echo "" | base64 -D > icon-152.png 2>/dev/null || echo "" | base64 --decode > icon-152.png && echo "✅ icon-152.png"
echo "" | base64 -D > icon-180.png 2>/dev/null || echo "" | base64 --decode > icon-180.png && echo "✅ icon-180.png"
echo "" | base64 -D > icon-192.png 2>/dev/null || echo "" | base64 --decode > icon-192.png && echo "✅ icon-192.png"
echo "" | base64 -D > icon.png 2>/dev/null || echo "" | base64 --decode > icon.png && echo "✅ icon.png"
echo "" | base64 -D > icon-maskable.png 2>/dev/null || echo "" | base64 --decode > icon-maskable.png && echo "✅ icon-maskable.png"

echo ""
echo "🚀 Deploying zu Netlify..."
npx netlify deploy --prod

echo "✅ Fertig!"